		lines++
	}
	job.Lines = lines

	// Check minified / generated
	if lines > 0 && int(job.Bytes)/int(lines) > opts.MinGenLineLength {
		job.Minified = true
	}
	checkHeaderLen := len(content)
	if checkHeaderLen > 2000 {
		checkHeaderLen = 2000
	}
	header := strings.ToLower(string(content[:checkHeaderLen]))
	for _, marker := range opts.GeneratedMarkers {
		if strings.Contains(header, strings.ToLower(marker)) {
			job.Generated = true
			break
		}
	}

	// Process lines
	rawLines := bytes.Split(content, []byte("\n"))
	uniqueLines := make(map[string]struct{})

	inML := false
	mlDepth := 0
	currentMLStart := ""
	currentMLEnd := ""

	var maxLineLen int64 = 0

	for _, rawLine := range rawLines {
		rawLineNoCR := bytes.TrimSuffix(rawLine, []byte("\r"))
		lineStr := string(rawLineNoCR)
		lineRuneCount := int64(len([]rune(lineStr)))
		if lineRuneCount > maxLineLen {
			maxLineLen = lineRuneCount
		}

		trimmed := strings.TrimSpace(lineStr)
		if len(trimmed) == 0 {
			job.Blank++
			if opts.Uloc || opts.Dryness {
				uniqueLines[""] = struct{}{}
			}
			continue
		}

		if opts.Uloc || opts.Dryness {
			uniqueLines[trimmed] = struct{}{}
		}

		// State machine for line
		hasCode := false
		hasComment := false
		lineComplexity := 0

		pos := 0
		runes := []rune(trimmed)
		n := len(runes)

		for pos < n {
			if inML {
				// Check end of ML
				if strings.HasPrefix(trimmed[pos:], currentMLEnd) {
					inML = false
					hasComment = true
					pos += len([]rune(currentMLEnd))
					continue
				}
				// Check nested ML start if supported
				if lang != nil && lang.Nested && currentMLStart != "" && strings.HasPrefix(trimmed[pos:], currentMLStart) {
					mlDepth++
					hasComment = true
					pos += len([]rune(currentMLStart))
					continue
				}
				hasComment = true
				pos++
				continue
			}

			// Check line comments
			matchedLineComment := false
			if lang != nil {
				for _, lc := range lang.LineComments {
					if lc != "" && strings.HasPrefix(trimmed[pos:], lc) {
						hasComment = true
						matchedLineComment = true
						break
					}
				}
			}
			if matchedLineComment {
				break // Rest of line is line comment
			}

			// Check multi-line comment start
			matchedMLStart := false
			if lang != nil {
				for _, ml := range lang.MultiLine {
					start, end := ml[0], ml[1]
					if start != "" && strings.HasPrefix(trimmed[pos:], start) {
						inML = true
						mlDepth = 1
						currentMLStart = start
						currentMLEnd = end
						hasComment = true
						matchedMLStart = true
						pos += len([]rune(start))
						break
					}
				}
			}
			if matchedMLStart {
				continue
			}

			// Check quotes / string literals
			matchedQuote := false
			if lang != nil {
				for _, q := range lang.Quotes {
					open, close := q[0], q[1]
					if open != "" && strings.HasPrefix(trimmed[pos:], open) {
						hasCode = true
						matchedQuote = true
						pos += len([]rune(open))
						// Consume string until close quote
						for pos < n {
							if runes[pos] == '\\' && open != "`" {
								pos += 2 // skip escaped char
								continue
							}
							if strings.HasPrefix(trimmed[pos:], close) {
								pos += len([]rune(close))
								break
							}
							pos++
						}
						break
					}
				}
			}
			if matchedQuote {
				continue
			}

			// Code character
			hasCode = true
			pos++
		}

		if hasCode {
			job.Code++
			// Count complexity in code line if enabled
			if !opts.NoComplexity && lang != nil && len(lang.ComplexityKeywords) > 0 {
				lineComplexity = countComplexity(trimmed, lang)
				job.Complexity += int64(lineComplexity)
			}
		} else if hasComment {
			job.Comment++
		} else {
			job.Code++
		}
	}

	job.MaxLineLength = maxLineLen
	if opts.Uloc || opts.Dryness {
		job.Uloc = int64(len(uniqueLines))
	}

	return job
}

func countComplexity(line string, lang *Language) int {
	if len(lang.ComplexityKeywords) == 0 {
		return 0
	}
	count := 0
	lower := strings.ToLower(line)
	for _, kw := range lang.ComplexityKeywords {
		kwLower := strings.ToLower(kw)
		idx := 0
		for {
			found := strings.Index(lower[idx:], kwLower)
			if found == -1 {
				break
			}
			actualIdx := idx + found
			// Check word boundary
			validLeft := actualIdx == 0 || isBoundaryRune(rune(lower[actualIdx-1]))
			rightIdx := actualIdx + len(kwLower)
			validRight := rightIdx >= len(lower) || isBoundaryRune(rune(lower[rightIdx]))
			if validLeft && validRight {
				count++
			}
			idx = actualIdx + len(kwLower)
		}
	}
	return count
}

func isBoundaryRune(r rune) bool {
	return !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_'
}
EOF
"}

