package processor

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

type CocomoResult struct {
	ProjectType    string
	Cost           float64
	ScheduleMonths float64
	People         float64
}

func CalculateCocomo(totalCode int64, opts *Options) CocomoResult {
	ksloc := float64(totalCode) / 1000.0

	a, b, c, d := 2.4, 1.05, 2.5, 0.38
	projectType := opts.CocomoProjectType

	switch strings.ToLower(projectType) {
	case "organic":
		a, b, c, d = 2.4, 1.05, 2.5, 0.38
	case "semi-detached":
		a, b, c, d = 3.0, 1.12, 2.5, 0.35
	case "embedded":
		a, b, c, d = 3.6, 1.20, 2.5, 0.32
	default:
		if strings.HasPrefix(projectType, "custom,") {
			parts := strings.Split(projectType, ",")
			if len(parts) == 5 {
				a, _ = strconv.ParseFloat(parts[1], 64)
				b, _ = strconv.ParseFloat(parts[2], 64)
				c, _ = strconv.ParseFloat(parts[3], 64)
				d, _ = strconv.ParseFloat(parts[4], 64)
			}
		}
	}

	effort := a * math.Pow(ksloc, b) * opts.EAF
	scheduleMonths := c * math.Pow(effort, d)
	people := 0.0
	if scheduleMonths > 0 {
		people = effort / scheduleMonths
	}

	monthlyWage := float64(opts.AvgWage) / 12.0
	cost := effort * monthlyWage * opts.Overhead

	return CocomoResult{
		ProjectType:    projectType,
		Cost:           cost,
