{"command":"cat <<'EOF' > processor/locomo.go
package processor

import (
	"math"
	"strings"
)

type LocomoResult struct {
	Preset                       string
	Cost                         float64
	InputTokens                  float64
	OutputTokens                 float64
	GenerationSeconds            float64
	ReviewHours                  float64
	AverageComplexityMultiplier float64
	Cycles                       float64
}

func CalculateLocomo(totalCode int64, totalComplexity int64, opts *Options) LocomoResult {
	preset := strings.ToLower(opts.LocomoPreset)
	inputPrice := 3.0
	outputPrice := 15.0
	tps := 50.0

	switch preset {
	case "large":
		inputPrice = 15.0
		outputPrice = 20.0
		tps = 30.0
	case "small":
		inputPrice = 0.50
		outputPrice = 2.00
		tps = 100.0
	case "local":
		inputPrice = 0.00
		outputPrice = 0.00
		tps = 15.0
	default:
		preset = "medium"
		inputPrice = 3.00
		outputPrice = 15.00
		tps = 50.0
	}

	if opts.LocomoInputPrice > 0 {
		inputPrice = opts.LocomoInputPrice
	}
	if opts.LocomoOutputPrice > 0 {
		outputPrice = opts.LocomoOutputPrice
	}
	if opts.LocomoTps > 0 {
		tps = opts.LocomoTps
	}

	r := 0.0
	if totalCode > 0 {
		r = float64(totalComplexity) / float64(totalCode)
	}

	cycles := 1.5 + 2.0*math.Sqrt(r)
	if opts.LocomoCycles > 0 {
		cycles = opts.LocomoCycles
	}

	compMult := cycles * (1.0 + 5.0*math.Sqrt(r))

	inputTokens := float64(totalCode) * 20.0 * compMult
	outputTokens := float64(totalCode) * 15.0

	cost := (inputTokens * inputPrice / 1000000.0) + (outputTokens * outputPrice / 1000000.0)

	genSeconds := 0.0
	if tps > 0 {
		genSeconds = outputTokens / tps
	}

	reviewMinutes := opts.LocomoReview
	if reviewMinutes == 0 {
		reviewMinutes = 0.01
	}
	reviewHours := (float64(totalCode) * reviewMinutes) / 60.0

	return LocomoResult{
		Preset:                       preset,
		Cost:                         cost,
		InputTokens:                  inputTokens,
		OutputTokens:                 outputTokens,
		GenerationSeconds:            genSeconds,
		ReviewHours:                  reviewHours,
		AverageComplexityMultiplier: compMult,
		Cycles:                       cycles,
	}
}
EOF
"}

