func FormatResults(summaries []*LanguageSummary, opts *Options) (string, error) {
	switch strings.ToLower(opts.Format) {
	case "json":
		return formatJSON(summaries, opts)
	case "json2":
		return formatJSON2(summaries, opts)
	case "csv":
		return formatCSV(summaries, opts)
	case "csv-stream":
		return formatCSVStream(summaries, opts)
	case "cloc-yaml":
		return formatClocYAML(summaries, opts)
	case "html":
		return formatHTML(summaries, opts, false)
	case "html-table":
		return formatHTML(summaries, opts, true)
	case "sql":
		return formatSQL(summaries, opts, false)
	case "sql-insert":
		return formatSQL(summaries, opts, true)
	case "openmetrics":
		return formatOpenMetrics(summaries, opts)
	case "wide":
		return formatTabular(summaries, opts, true)
	default:
		return formatTabular(summaries, opts, opts.Wide)
	}
}

func formatNumber(val int64) string {
	s := fmt.Sprintf("%d", val)
	if val < 0 {
		s = s[1:]
	}
	var parts []string
	for len(s) > 3 {
		parts = append([]string{s[len(s)-3:]}, parts...)
		s = s[:len(s)-3]
	}
	if len(s) > 0 {
		parts = append([]string{s}, parts...)
	}
	res := strings.Join(parts, ",")
	if val < 0 {
		res = "-" + res
	}
	return res
}

func formatTabular(summaries []*LanguageSummary, opts *Options, isWide bool) (string, error) {
	var sb strings.Builder

	borderChar := "─"
	if opts.CI {
		borderChar = "-"
	}

	borderLen := 79
	if isWide {
		borderLen = 109
	}

	border := strings.Repeat(borderChar, borderLen)

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	if isWide {
		sb.WriteString(fmt.Sprintf("%-36s %9s %10s %9s %10s %9s %11s %17s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"))
	} else {
		sb.WriteString(fmt.Sprintf("%-19s %9s %12s %9s %10s %11s %11s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	}

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	var totFiles, totLines, totBlanks, totComments, totCode, totComplexity, totBytes, totUloc int64

	for _, s := range summaries {
		totFiles += s.Count
		totLines += s.Lines
		totBlanks += s.Blank
		totComments += s.Comment
		totCode += s.Code
		totComplexity += s.Complexity
		totBytes += s.Bytes
		totUloc += s.ULOC

		if isWide {
			compPerLines := 0.0
			if s.Lines > 0 {
				compPerLines = (float64(s.Complexity) / float64(s.Lines)) * 100.0
			}
			sb.WriteString(fmt.Sprintf("%-36s %9s %10s %9s %10s %9s %11s %17.2f\n",
				s.Name,
				formatNumber(s.Count),
				formatNumber(s.Lines),
				formatNumber(s.Blank),
				formatNumber(s.Comment),
				formatNumber(s.Code),
				formatNumber(s.Complexity),
				compPerLines,
			))
		} else {
			sb.WriteString(fmt.Sprintf("%-19s %9s %12s %9s %10s %11s %11s\n",
				s.Name,
				formatNumber(s.Count),
				formatNumber(s.Lines),
				formatNumber(s.Blank),
				formatNumber(s.Comment),
				formatNumber(s.Code),
				formatNumber(s.Complexity),
			))
		}

		if opts.Character {
			mean := int64(0)
			if s.Lines > 0 {
				mean = s.Bytes / s.Lines
			}
			sb.WriteString(fmt.Sprintf("%-19s %9s %12s\n",
				"MaxLine / MeanLine",
				formatNumber(s.MaxLineLength),
				formatNumber(mean),
			))
		}

		if opts.Uloc {
			sb.WriteString(fmt.Sprintf("%-19s %32s\n", "(ULOC)", formatNumber(s.ULOC)))
		}

		if opts.ByFile {
			if !opts.NoHborder {
				sb.WriteString(border + "\n")
			}
			for _, f := range s.Files {
				dispLoc := f.Location
				if len(dispLoc) > 27 {
					dispLoc = "~" + dispLoc[len(dispLoc)-26:]
				}
				sb.WriteString(fmt.Sprintf("%-27s %10s %9s %10s %11s %11s\n",
					dispLoc,
					formatNumber(f.Lines),
					formatNumber(f.Blank),
					formatNumber(f.Comment),
					formatNumber(f.Code),
					formatNumber(f.Complexity),
				))
			}
			if !opts.NoHborder {
				sb.WriteString(border + "\n")
			}
		}
	}

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	if isWide {
		totCompPerLines := 0.0
		if totLines > 0 {
			totCompPerLines = (float64(totComplexity) / float64(totLines)) * 100.0
		}
		sb.WriteString(fmt.Sprintf("%-36s %9s %10s %9s %10s %9s %11s %17.2f\n",
			"Total",
			formatNumber(totFiles),
			formatNumber(totLines),
			formatNumber(totBlanks),
			formatNumber(totComments),
			formatNumber(totCode),
			formatNumber(totComplexity),
			totCompPerLines,
		))
	} else {
		sb.WriteString(fmt.Sprintf("%-19s %9s %12s %9s %10s %11s %11s\n",
			"Total",
			formatNumber(totFiles),
			formatNumber(totLines),
			formatNumber(totBlanks),
			formatNumber(totComments),
			formatNumber(totCode),
			formatNumber(totComplexity),
		))
	}

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	if opts.Uloc {
		sb.WriteString(fmt.Sprintf("Unique Lines of Code (ULOC)        %d\n", totUloc))
	}

	if opts.Dryness {
		dryness := 0.0
		if totLines > 0 {
			dryness = float64(totUloc) / float64(totLines)
		}
		sb.WriteString(fmt.Sprintf("DRYness %%                        %.2f\n", dryness))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if opts.SloccountFormat {
		coc := CalculateCocomo(totCode, opts)
		personYears := coc.ScheduleMonths / 12.0
		sb.WriteString(fmt.Sprintf("Total Physical Source Lines of Code (SLOC)                     = %d\n", totCode))
		sb.WriteString(fmt.Sprintf("Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n", personYears, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Person-Months = 2.40*(KSLOC**1.05)*1.00)\n"))
		sb.WriteString(fmt.Sprintf("Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n", personYears, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Months = 2.50*(person-months**0.38))\n"))
		sb.WriteString(fmt.Sprintf("Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n", coc.People))
		sb.WriteString(fmt.Sprintf("Total Estimated Cost to Develop                                = %s\n", FormatMoney(coc.Cost, opts.CurrencySymbol)))
		sb.WriteString(fmt.Sprintf(" (average salary = $%s/year, overhead = %.2f)\n", formatNumber(opts.AvgWage), opts.Overhead))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	} else if !opts.NoCocomo {
		coc := CalculateCocomo(totCode, opts)
		sb.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s\n", coc.ProjectType, FormatMoney(coc.Cost, opts.CurrencySymbol)))
		sb.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", coc.ProjectType, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", coc.ProjectType, coc.People))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if opts.Locomo || opts.CostComparison {
		loc := CalculateLocomo(totCode, totComplexity, opts)
		sb.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", loc.Preset))
		sb.WriteString(fmt.Sprintf("  Tokens Required (in/out) %.1fM / %.1fM\n", loc.InputTokens/1000000.0, loc.OutputTokens/1000000.0))
		sb.WriteString(fmt.Sprintf("  Cost to Generate $%d\n", int64(math.Round(loc.Cost))))
		sb.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", loc.Cycles))
		sb.WriteString(fmt.Sprintf("  Generation Time (serial) %.1f minutes\n", loc.GenerationSeconds/60.0))
		sb.WriteString(fmt.Sprintf("  Human Review Time %.1f hours\n", loc.ReviewHours))
		sb.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
		sb.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if !opts.NoSize {
		mb := float64(totBytes) / 1000000.0
		sb.WriteString(fmt.Sprintf("Processed %d bytes, %.3f megabytes (%s)\n", totBytes, mb, strings.ToUpper(opts.SizeUnit)))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	return sb.String(), nil
}

func formatJSON(summaries []*LanguageSummary, opts *Options) (string, error) {
	var list []*LanguageSummary
	for _, s := range summaries {
		item := *s
		if !opts.ByFile {
			item.Files = []*FileJob{}
		}
		list = append(list, &item)
	}
	bs, err := json.Marshal(list)
	if err != nil {
		return "", err
	}
	return string(bs), nil
}

func formatJSON2(summaries []*LanguageSummary, opts *Options) (string, error) {
	var list []*LanguageSummary
	var totCode, totComplexity int64
	for _, s := range summaries {
		item := *s
		if !opts.ByFile {
			item.Files = []*FileJob{}
		}
		totCode += s.Code
		totComplexity += s.Complexity
		list = append(list, &item)
	}

	coc := CalculateCocomo(totCode, opts)

	resp := map[string]interface{}{
		"languageSummary":         list,
		"estimatedCost":           coc.Cost,
		"estimatedScheduleMonths": coc.ScheduleMonths,
		"estimatedPeople":         coc.People,
	}

	if opts.Locomo {
		loc := CalculateLocomo(totCode, totComplexity, opts)
		resp["estimatedLLMCost"] = loc.Cost
		resp["estimatedLLMInputTokens"] = loc.InputTokens
		resp["estimatedLLMOutputTokens"] = loc.OutputTokens
		resp["estimatedLLMGenerationSeconds"] = loc.GenerationSeconds
		resp["estimatedLLMReviewHours"] = loc.ReviewHours
		resp["estimatedLLMPreset"] = loc.Preset
		resp["estimatedLLMAverageComplexityMultiplier"] = loc.AverageComplexityMultiplier
		resp["estimatedLLMCycles"] = loc.Cycles
	}

	bs, err := json.Marshal(resp)
	if err != nil {
		return "", err
	}
	return string(bs), nil
}

func formatCSV(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	sb.WriteString("Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
			s.Name, s.Lines, s.Code, s.Comment, s.Blank, s.Complexity, s.Bytes, s.Count, s.ULOC))
	}
	return sb.String(), nil
}

func formatCSVStream(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	for _, s := range summaries {
		for _, f := range s.Files {
			sb.WriteString(fmt.Sprintf("%s,\"%s\",\"%s\",%d,%d,%d,%d,%d,%d,%d\n",
				f.Language, f.Location, f.Filename, f.Lines, f.Code, f.Comment, f.Blank, f.Complexity, f.Bytes, f.Uloc))
		}
	}
	return sb.String(), nil
}

func formatClocYAML(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	var totFiles, totLines, totCode, totComments, totBlanks int64
	for _, s := range summaries {
		totFiles += s.Count
		totLines += s.Lines
		totCode += s.Code
		totComments += s.Comment
