	}

	sb.WriteString("# https://github.com/boyter/scc/\n")
	sb.WriteString("header:\n")
	sb.WriteString("  url: https://github.com/boyter/scc/\n")
	sb.WriteString("  version: 3.7.0\n")
	sb.WriteString("  elapsed_seconds: 0.001\n")
