	sb.WriteString("# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")

	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("scc_files{language=\"%s\"} %d\n", s.Name, s.Count))
		sb.WriteString(fmt.Sprintf("scc_lines{language=\"%s\"} %d\n", s.Name, s.Lines))
		sb.WriteString(fmt.Sprintf("scc_code{language=\"%s\"} %d\n", s.Name, s.Code))
		sb.WriteString(fmt.Sprintf("scc_comments{language=\"%s\"} %d\n", s.Name, s.Comment))
		sb.WriteString(fmt.Sprintf("scc_blanks{language=\"%s\"} %d\n", s.Name, s.Blank))
		sb.WriteString(fmt.Sprintf("scc_complexity{language=\"%s\"} %d\n", s.Name, s.Complexity))
		sb.WriteString(fmt.Sprintf("scc_bytes{language=\"%s\"} %d\n", s.Name, s.Bytes))
	}

	return sb.String(), nil
}
