			sb.WriteString(fmt.Sprintf("%-36s %9s %10s %9s %10s %9s %11s %17.2f\n",
				s.Name,
				formatNumber(s.Count),
				formatNumber(s.Lines),
				formatNumber(s.Blank),
				formatNumber(s.Comment),
				formatNumber(s.Code),
				formatNumber(s.Complexity),
				compPerLines,
			))
		} else {
			sb.WriteString(fmt.Sprintf("%-19s %9s %12s %9s %10s %11s %11s\n",
				s.Name,
				formatNumber(s.Count),
				formatNumber(s.Lines),
				formatNumber(s.Blank),
				formatNumber(s.Comment),
				formatNumber(s.Code),
				formatNumber(s.Complexity),
			))
		}

		if opts.Character {
			mean := int64(0)
			if s.Lines > 0 {
				mean = s.Bytes / s.Lines
			}
			sb.WriteString(fmt.Sprintf("%-19s %9s %12s\n",
				"MaxLine / MeanLine",
				formatNumber(s.MaxLineLength),
				formatNumber(mean),
			))
		}

		if opts.Uloc {
			sb.WriteString(fmt.Sprintf("%-19s %32s\n", "(ULOC)", formatNumber(s.ULOC)))
		}

		if opts.ByFile {
			if !opts.NoHborder {
				sb.WriteString(border + "\n")
			}
			for _, f := range s.Files {
				dispLoc := f.Location
				if len(dispLoc) > 27 {
					dispLoc = "~" + dispLoc[len(dispLoc)-26:]
				}
				sb.WriteString(fmt.Sprintf("%-27s %10s %9s %10s %11s %11s\n",
					dispLoc,
					formatNumber(f.Lines),
					formatNumber(f.Blank),
					formatNumber(f.Comment),
					formatNumber(f.Code),
					formatNumber(f.Complexity),
				))
			}
			if !opts.NoHborder {
				sb.WriteString(border + "\n")
			}
		}
	}

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	if isWide {
		totCompPerLines := 0.0
		if totLines > 0 {
			totCompPerLines = (float64(totComplexity) / float64(totLines)) * 100.0
		}
		sb.WriteString(fmt.Sprintf("%-36s %9s %10s %9s %10s %9s %11s %17.2f\n",
			"Total",
			formatNumber(totFiles),
			formatNumber(totLines),
			formatNumber(totBlanks),
			formatNumber(totComments),
			formatNumber(totCode),
			formatNumber(totComplexity),
			totCompPerLines,
		))
	} else {
		sb.WriteString(fmt.Sprintf("%-19s %9s %12s %9s %10s %11s %11s\n",
			"Total",
			formatNumber(totFiles),
			formatNumber(totLines),
			formatNumber(totBlanks),
			formatNumber(totComments),
			formatNumber(totCode),
			formatNumber(totComplexity),
		))
	}

	if !opts.NoHborder {
		sb.WriteString(border + "\n")
	}

	if opts.Uloc {
		sb.WriteString(fmt.Sprintf("Unique Lines of Code (ULOC)        %d\n", totUloc))
	}

	if opts.Dryness {
		dryness := 0.0
		if totLines > 0 {
			dryness = float64(totUloc) / float64(totLines)
		}
		sb.WriteString(fmt.Sprintf("DRYness %%                        %.2f\n", dryness))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if opts.SloccountFormat {
		coc := CalculateCocomo(totCode, opts)
		personYears := coc.ScheduleMonths / 12.0
		sb.WriteString(fmt.Sprintf("Total Physical Source Lines of Code (SLOC)                     = %d\n", totCode))
		sb.WriteString(fmt.Sprintf("Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n", personYears, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Person-Months = 2.40*(KSLOC**1.05)*1.00)\n"))
		sb.WriteString(fmt.Sprintf("Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n", personYears, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf(" (Basic COCOMO model, Months = 2.50*(person-months**0.38))\n"))
		sb.WriteString(fmt.Sprintf("Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n", coc.People))
		sb.WriteString(fmt.Sprintf("Total Estimated Cost to Develop                                = %s\n", FormatMoney(coc.Cost, opts.CurrencySymbol)))
		sb.WriteString(fmt.Sprintf(" (average salary = $%s/year, overhead = %.2f)\n", formatNumber(opts.AvgWage), opts.Overhead))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	} else if !opts.NoCocomo {
		coc := CalculateCocomo(totCode, opts)
		sb.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s\n", coc.ProjectType, FormatMoney(coc.Cost, opts.CurrencySymbol)))
		sb.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", coc.ProjectType, coc.ScheduleMonths))
		sb.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", coc.ProjectType, coc.People))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if opts.Locomo || opts.CostComparison {
		loc := CalculateLocomo(totCode, totComplexity, opts)
		sb.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", loc.Preset))
		sb.WriteString(fmt.Sprintf("  Tokens Required (in/out) %.1fM / %.1fM\n", loc.InputTokens/1000000.0, loc.OutputTokens/1000000.0))
		sb.WriteString(fmt.Sprintf("  Cost to Generate $%d\n", int64(math.Round(loc.Cost))))
		sb.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", loc.Cycles))
		sb.WriteString(fmt.Sprintf("  Generation Time (serial) %.1f minutes\n", loc.GenerationSeconds/60.0))
		sb.WriteString(fmt.Sprintf("  Human Review Time %.1f hours\n", loc.ReviewHours))
		sb.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
		sb.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	if !opts.NoSize {
		mb := float64(totBytes) / 1000000.0
		sb.WriteString(fmt.Sprintf("Processed %d bytes, %.3f megabytes (%s)\n", totBytes, mb, strings.ToUpper(opts.SizeUnit)))
		if !opts.NoHborder {
			sb.WriteString(border + "\n")
		}
	}

	return sb.String(), nil
}

func formatJSON(summaries []*LanguageSummary, opts *Options) (string, error) {
	var list []*LanguageSummary
	for _, s := range summaries {
		item := *s
		if !opts.ByFile {
			item.Files = []*FileJob{}
		}
		list = append(list, &item)
	}
	bs, err := json.Marshal(list)
	if err != nil {
		return "", err
	}
	return string(bs), nil
}

func formatJSON2(summaries []*LanguageSummary, opts *Options) (string, error) {
	var list []*LanguageSummary
	var totCode, totComplexity int64
	for _, s := range summaries {
		item := *s
		if !opts.ByFile {
			item.Files = []*FileJob{}
		}
		totCode += s.Code
		totComplexity += s.Complexity
		list = append(list, &item)
	}

	coc := CalculateCocomo(totCode, opts)

	resp := map[string]interface{}{
		"languageSummary":         list,
		"estimatedCost":           coc.Cost,
		"estimatedScheduleMonths": coc.ScheduleMonths,
		"estimatedPeople":         coc.People,
	}

	if opts.Locomo {
		loc := CalculateLocomo(totCode, totComplexity, opts)
		resp["estimatedLLMCost"] = loc.Cost
		resp["estimatedLLMInputTokens"] = loc.InputTokens
		resp["estimatedLLMOutputTokens"] = loc.OutputTokens
		resp["estimatedLLMGenerationSeconds"] = loc.GenerationSeconds
		resp["estimatedLLMReviewHours"] = loc.ReviewHours
		resp["estimatedLLMPreset"] = loc.Preset
		resp["estimatedLLMAverageComplexityMultiplier"] = loc.AverageComplexityMultiplier
		resp["estimatedLLMCycles"] = loc.Cycles
	}

	bs, err := json.Marshal(resp)
	if err != nil {
		return "", err
	}
	return string(bs), nil
}

func formatCSV(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	sb.WriteString("Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
			s.Name, s.Lines, s.Code, s.Comment, s.Blank, s.Complexity, s.Bytes, s.Count, s.ULOC))
	}
	return sb.String(), nil
}

func formatCSVStream(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	for _, s := range summaries {
		for _, f := range s.Files {
			sb.WriteString(fmt.Sprintf("%s,\"%s\",\"%s\",%d,%d,%d,%d,%d,%d,%d\n",
				f.Language, f.Location, f.Filename, f.Lines, f.Code, f.Comment, f.Blank, f.Complexity, f.Bytes, f.Uloc))
		}
	}
	return sb.String(), nil
}

func formatClocYAML(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	var totFiles, totLines, totCode, totComments, totBlanks int64
	for _, s := range summaries {
		totFiles += s.Count
		totLines += s.Lines
		totCode += s.Code
		totComments += s.Comment
		totBlanks += s.Blank
	}

	sb.WriteString("# https://github.com/boyter/scc/\n")
	sb.WriteString("header:\n")
	sb.WriteString("  url: https://github.com/boyter/scc/\n")
	sb.WriteString("  version: 3.7.0\n")
	sb.WriteString("  elapsed_seconds: 0.001\n")
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", totFiles))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", totLines))
	sb.WriteString("  files_per_second: 3000\n")
	sb.WriteString("  lines_per_second: 32000\n")

	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s:\n", s.Name))
		sb.WriteString(fmt.Sprintf("  name: %s\n", s.Name))
		sb.WriteString(fmt.Sprintf("  code: %d\n", s.Code))
		sb.WriteString(fmt.Sprintf("  comment: %d\n", s.Comment))
		sb.WriteString(fmt.Sprintf("  blank: %d\n", s.Blank))
		sb.WriteString(fmt.Sprintf("  nFiles: %d\n", s.Count))
	}

	sb.WriteString("SUM:\n")
	sb.WriteString(fmt.Sprintf("  code: %d\n", totCode))
	sb.WriteString(fmt.Sprintf("  comment: %d\n", totComments))
	sb.WriteString(fmt.Sprintf("  blank: %d\n", totBlanks))
	sb.WriteString(fmt.Sprintf("  nFiles: %d\n", totFiles))

	return sb.String(), nil
}

func formatHTML(summaries []*LanguageSummary, opts *Options, tableOnly bool) (string, error) {
	var sb strings.Builder

	if !tableOnly {
		sb.WriteString("<html lang=\"en\"><head><meta charset=\"utf-8\" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>")
	}

	sb.WriteString("<table id=\"scc-table\">\n\t<thead><tr>\n")
	sb.WriteString("\t\t<th>Language</th>\n\t\t<th>Files</th>\n\t\t<th>Lines</th>\n\t\t<th>Blank</th>\n\t\t<th>Comment</th>\n\t\t<th>Code</th>\n\t\t<th>Complexity</th>\n\t\t<th>Bytes</th>\n\t\t<th>Uloc</th>\n")
	sb.WriteString("\t</tr></thead>\n\t<tbody>")

	var totFiles, totLines, totBlanks, totComments, totCode, totComplexity, totBytes, totUloc int64

	for _, s := range summaries {
		totFiles += s.Count
		totLines += s.Lines
		totBlanks += s.Blank
		totComments += s.Comment
		totCode += s.Code
		totComplexity += s.Complexity
		totBytes += s.Bytes
		totUloc += s.ULOC

		sb.WriteString(fmt.Sprintf("<tr>\n\t\t<th>%s</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>",
			s.Name, s.Count, s.Lines, s.Blank, s.Comment, s.Code, s.Complexity, s.Bytes, s.ULOC))
	}

	sb.WriteString("</tbody>\n\ttfoot><tr>\n")
	sb.WriteString(fmt.Sprintf("\t\t<th>Total</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>\n",
		totFiles, totLines, totBlanks, totComments, totCode, totComplexity, totBytes, totUloc))

	coc := CalculateCocomo(totCode, opts)
	sb.WriteString(fmt.Sprintf("\t<tr>\n\t\t<th colspan=\"9\">Estimated Cost to Develop (%s) %s<br>Estimated Schedule Effort (%s) %.2f months<br>Estimated People Required (%s) %.2f<br></th>\n\t</tr></tfoot>\n\t</table>",
		coc.ProjectType, FormatMoney(coc.Cost, opts.CurrencySymbol), coc.ProjectType, coc.ScheduleMonths, coc.ProjectType, coc.People))

	if !tableOnly {
		sb.WriteString("</body></html>")
	}

	return sb.String(), nil
}

func formatSQL(summaries []*LanguageSummary, opts *Options, insertOnly bool) (string, error) {
	var sb strings.Builder

	proj := opts.SqlProject
	if proj == "" && len(opts.Paths) > 0 {
		proj = opts.Paths[0]
	}

	if !insertOnly {
		sb.WriteString("create table metadata (   -- github.com/boyter/scc v 3.7.0\n")
		sb.WriteString("             timestamp text,\n             Project   text,\n             elapsed_s real,\n             estimated_cost real,\n             estimated_schedule_months real,\n             estimated_people real);\n")
		sb.WriteString("create table t        (\n             Project       text   ,\n             Language      text   ,\n             File          text   ,\n             File_dirname  text   ,\n             File_basename text   ,\n             nByte         integer,\n             nBlank        integer,\n             nComment      integer,\n             nCode         integer,\n             nComplexity   integer,\n             nUloc         integer    \n);\n")
	}

	sb.WriteString("begin transaction;\n")
	var totCode int64
	for _, s := range summaries {
		totCode += s.Code
		for _, f := range s.Files {
			dir := filepath.Dir(f.Location) + "/"
			sb.WriteString(fmt.Sprintf("insert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);\n",
				proj, f.Language, f.Location, dir, f.Filename, f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
		}
	}
	sb.WriteString("commit;\n")

	coc := CalculateCocomo(totCode, opts)
	now := time.Now().Format("2006-01-02 15:04:05")

	sb.WriteString("begin transaction;\n")
	sb.WriteString(fmt.Sprintf("insert into metadata values('%s', '%s', 0.001000, %f, %f, %f);\n",
		now, proj, coc.Cost, coc.ScheduleMonths, coc.People))
	sb.WriteString("commit;\n")

	return sb.String(), nil
}

func formatOpenMetrics(summaries []*LanguageSummary, opts *Options) (string, error) {
	var sb strings.Builder
	sb.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n")
	sb.WriteString("# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n")
	sb.WriteString("# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n")
	sb.WriteString("# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n")
	sb.WriteString("# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n")
	sb.WriteString("# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n")
	sb.WriteString("# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")

	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("scc_files{language=\"%s\"} %d\n", s.Name, s.Count))
		sb.WriteString(fmt.Sprintf("scc_lines{language=\"%s\"} %d\n", s.Name, s.Lines))
		sb.WriteString(fmt.Sprintf("scc_code{language=\"%s\"} %d\n", s.Name, s.Code))
		sb.WriteString(fmt.Sprintf("scc_comments{language=\"%s\"} %d\n", s.Name, s.Comment))
		sb.WriteString(fmt.Sprintf("scc_blanks{language=\"%s\"} %d\n", s.Name, s.Blank))
		sb.WriteString(fmt.Sprintf("scc_complexity{language=\"%s\"} %d\n", s.Name, s.Complexity))
		sb.WriteString(fmt.Sprintf("scc_bytes{language=\"%s\"} %d\n", s.Name, s.Bytes))
	}

	return sb.String(), nil
}
