{"command":"cat <<'EOF' > mcp/server.go
package mcp

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"scc/processor"
	"strings"
)

type Request struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      interface{}     `json:"id"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
}

type Response struct {
	JSONRPC string      `json:"jsonrpc"`
	ID      interface{} `json:"id"`
	Result  interface{} `json:"result,omitempty"`
	Error   *ErrorObj   `json:"error,omitempty"`
}

type ErrorObj struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

func RunServer() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}

		var req Request
		err := json.Unmarshal(line, &req)
		if err != nil {
			sendError(nil, -32700, "Parse error")
			continue
		}

		handleRequest(&req)
	}
}

func sendError(id interface{}, code int, msg string) {
	resp := Response{
		JSONRPC: "2.0",
		ID:      id,
		Error: &ErrorObj{
			Code:    code,
			Message: msg,
		},
	}
	bs, _ := json.Marshal(resp)
	fmt.Println(string(bs))
}

func handleRequest(req *Request) {
	switch req.Method {
	case "initialize":
		resp := Response{
			JSONRPC: "2.0",
			ID:      req.ID,
			Result: map[string]interface{}{
				"protocolVersion": "2025-03-26",
				"capabilities":    map[string]interface{}{"tools": map[string]interface{}{}},
				"serverInfo":       map[string]interface{}{"name": "scc", "version": "3.7.0"},
			},
		}
		bs, _ := json.Marshal(resp)
		fmt.Println(string(bs))

	case "tools/list":
		tools := []map[string]interface{}{
			{
				"name":        "analyze",
				"description": "Count lines of code, comments, blanks and estimate complexity for a project directory or file. Supports 200+ languages.\n\nReturns per-language summary with:\n- files: number of source files\n- lines: total lines\n- code: lines of actual code\n- comment: lines of comments\n- blank: blank lines\n- complexity: estimated cyclomatic complexity\n- bytes: total size in bytes\n\nAlso returns COCOMO cost/schedule estimates and optionally LOCOMO (LLM cost) estimates.\n\nUse by_file with sort=complexity to find the most complex files in a project.",
				"annotations": map[string]interface{}{
					"readOnlyHint":    false,
					"destructiveHint": true,
					"idempotentHint":  false,
					"openWorldHint":   true,
				},
				"inputSchema": map[string]interface{}{
					"type": "object",
					"properties": map[string]interface{}{
						"by_file":       map[string]interface{}{"type": "boolean", "description": "If true, return per-file results instead of per-language summary. Useful with sort to find e.g. the most complex or largest files. Use with limit to control response size."},
						"exclude_ext":   map[string]interface{}{"type": "string", "description": "Comma-separated list of file extensions to exclude (e.g. 'json,xml')."},
						"include_ext":   map[string]interface{}{"type": "string", "description": "Comma-separated list of file extensions to include (e.g. 'go,java,js')."},
						"limit":         map[string]interface{}{"type": "number", "description": "Maximum number of files to return per language when by_file is true. Defaults to 10. Set to -1 for unlimited."},
						"locomo":        map[string]interface{}{"type": "boolean", "description": "Include LOCOMO (LLM Output COst MOdel) cost estimation in results."},
						"locomo_preset": map[string]interface{}{"type": "string", "description": "LOCOMO model preset: large (GPT-4/Opus class), medium (Sonnet class), small (Haiku class), local (local LLM). Default: medium."},
						"no_duplicates": map[string]interface{}{"type": "boolean", "description": "Remove duplicate files from stats."},
						"no_min_gen":    map[string]interface{}{"type": "boolean", "description": "Exclude minified or generated files."},
						"path":          map[string]interface{}{"type": "string", "description": "Directory or file path to analyze. Defaults to current directory."},
						"sort":          map[string]interface{}{"type": "string", "description": "Column to sort results by: files, name, lines, blank, code, comment, complexity, bytes. Default: files."},
					},
					"required": []interface{}{},
				},
			},
		}
		resp := Response{
			JSONRPC: "2.0",
			ID:      req.ID,
			Result:  map[string]interface{}{"tools": tools},
		}
		bs, _ := json.Marshal(resp)
		fmt.Println(string(bs))

	case "tools/call":
		var callParams struct {
			Name      string                 `json:"name"`
			Arguments map[string]interface{} `json:"arguments"`
		}
		json.Unmarshal(req.Params, &callParams)

		path := "."
		if p, ok := callParams.Arguments["path"].(string); ok && p != "" {
			path = p
		}

		opts := processor.DefaultOptions()
		opts.Paths = []string{path}

		if bf, ok := callParams.Arguments["by_file"].(bool); ok {
			opts.ByFile = bf
		}
		if s, ok := callParams.Arguments["sort"].(string); ok {
			opts.SortBy = s
		}
		if ie, ok := callParams.Arguments["include_ext"].(string); ok && ie != "" {
			opts.IncludeExt = strings.Split(ie, ",")
		}
		if ee, ok := callParams.Arguments["exclude_ext"].(string); ok && ee != "" {
			opts.ExcludeExt = strings.Split(ee, ",")
		}
		if nd, ok := callParams.Arguments["no_duplicates"].(bool); ok {
			opts.NoDuplicates = nd
		}
		if nmg, ok := callParams.Arguments["no_min_gen"].(bool); ok {
			opts.NoMinGen = nmg
		}
		if loc, ok := callParams.Arguments["locomo"].(bool); ok {
			opts.Locomo = loc
		}
		if lp, ok := callParams.Arguments["locomo_preset"].(string); ok && lp != "" {
			opts.LocomoPreset = lp
		}

		jobs, _ := processor.WalkAndProcess(opts)
		summaries := processor.GroupAndSortSummaries(jobs, opts)

		var langList []map[string]interface{}
		var totFiles, totLines, totCode, totComment, totBlank, totComplexity, totBytes int64

		for _, s := range summaries {
			totFiles += s.Count
			totLines += s.Lines
			totCode += s.Code
			totComment += s.Comment
			totBlank += s.Blank
			totComplexity += s.Complexity
			totBytes += s.Bytes

			langList = append(langList, map[string]interface{}{
				"name":       s.Name,
				"files":      s.Count,
				"lines":      s.Lines,
				"code":       s.Code,
				"comment":    s.Comment,
				"blank":      s.Blank,
				"complexity": s.Complexity,
				"bytes":      s.Bytes,
			})
		}

		coc := processor.CalculateCocomo(totCode, opts)

		resMap := map[string]interface{}{
			"path":       path,
			"languages":  langList,
			"totals": map[string]interface{}{
				"files":      totFiles,
				"lines":      totLines,
				"code":       totCode,
				"comment":    totComment,
				"blank":      totBlank,
				"complexity": totComplexity,
				"bytes":      totBytes,
			},
			"cocomo": map[string]interface{}{
				"estimatedCost":           coc.Cost,
				"estimatedScheduleMonths": coc.ScheduleMonths,
				"estimatedPeople":         coc.People,
			},
			"totalFiles": totFiles,
			"totalLines": totLines,
			"totalCode":  totCode,
		}

		resBS, _ := json.MarshalIndent(resMap, "", "  ")

		resp := Response{
			JSONRPC: "2.0",
			ID:      req.ID,
			Result: map[string]interface{}{
				"content": []map[string]interface{}{
					{
						"type": "text",
						"text": string(resBS),
					},
				},
			},
		}
		bs, _ := json.Marshal(resp)
		fmt.Println(string(bs))

	default:
		sendError(req.ID, -32601, "Method not found")
	}
}
EOF
"}

