	Debug                     bool
	Verbose                   bool
	Trace                     bool
	MCP                       bool
	RemapAll                  string
	RemapUnknown              string
	CountAs                   string
	NoComplexity              bool
}

func DefaultOptions() *Options {
	return &Options{
		AvgWage:           56286,
		Overhead:          2.4,
		EAF:               1.0,
		CurrencySymbol:    "$",
		CocomoProjectType: "organic",
		LocomoPreset:      "medium",
		LocomoReview:      0.01,
		MinGenLineLength:  255,
		GeneratedMarkers:  []string{"do not edit", "<auto-generated />"},
		LargeByteCount:    1000000,
		LargeLineCount:    40000,
		ExcludeDir:        []string{".git", ".hg", ".svn"},
		ExcludeFile:       []string{"package-lock.json", "Cargo.lock", "yarn.lock", "pubspec.lock", "Podfile.lock", "pnpm-lock.yaml"},
		Format:            "tabular",
		SortBy:            "files",
		SizeUnit:          "si",
	}
}

type IgnoreMatcher struct {
	patterns []string
}

func parseIgnoreFile(path string) *IgnoreMatcher {
	f, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer f.Close()

	var patterns []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		patterns = append(patterns, line)
	}
	return &IgnoreMatcher{patterns: patterns}
}

func (im *IgnoreMatcher) Matches(relPath string, isDir bool) bool {
	if im == nil {
		return false
	}
	name := filepath.Base(relPath)
	for _, p := range im.patterns {
		pClean := strings.TrimSuffix(p, "/")
		if matchPattern(pClean, name) || matchPattern(pClean, relPath) {
