	if matched {
		return true
	}
	if strings.Contains(s, pat) {
		return true
	}
	return false
}

func WalkAndProcess(opts *Options) ([]*FileJob, error) {
	var jobs []*FileJob
	seenHashes := make(map[string]bool)

	// Build language lookup map
	extMap := make(map[string]*Language)
	filenameMap := make(map[string]*Language)
	for i := range Languages {
		l := &Languages[i]
		for _, ext := range l.Extensions {
			extMap[strings.ToLower(ext)] = l
		}
		for _, fn := range l.Filenames {
			filenameMap[strings.ToLower(fn)] = l
		}
	}

