	if opts.CountAs != "" {
		parts := strings.Split(opts.CountAs, ",")
		for _, p := range parts {
			kv := strings.SplitN(p, ":", 2)
			if len(kv) == 2 {
				k := strings.TrimSpace(strings.Trim(kv[0], "\""))
				v := strings.TrimSpace(strings.Trim(kv[1], "\""))
				for i := range Languages {
					if strings.EqualFold(Languages[i].Name, v) {
						extMap[strings.ToLower(k)] = &Languages[i]
						filenameMap[strings.ToLower(k)] = &Languages[i]
						break
					}
				}
			}
		}
	}

	// NotMatch regexes
	var notMatchRegexes []*regexp.Regexp
	for _, pattern := range opts.NotMatch {
		re, err := regexp.Compile(pattern)
		if err == nil {
			notMatchRegexes = append(notMatchRegexes, re)
		}
	}

	paths := opts.Paths
	if len(paths) == 0 {
		paths = []string{"."}
	}

	for _, rootPath := range paths {
		info, err := os.Stat(rootPath)
		if err != nil {
			continue
		}

		if !info.IsDir() {
			job := processSingleFile(rootPath, extMap, filenameMap, opts)
			if job != nil {
				jobs = append(jobs, job)
			}
			continue
		}

		// Directory walk
		err = filepath.Walk(rootPath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}

			name := info.Name()
			if info.IsDir() {
				for _, ex := range opts.ExcludeDir {
					if strings.EqualFold(name, ex) {
						return filepath.SkipDir
					}
				}
				return nil
			}

			for _, exF := range opts.ExcludeFile {
				if strings.EqualFold(name, exF) && !opts.CountIgnore {
					return nil
				}
			}

			for _, re := range notMatchRegexes {
				if re.MatchString(path) {
					return nil
				}
			}

			content, err := os.ReadFile(path)
			if err != nil {
				return nil
			}

			if opts.NoDuplicates {
				h := sha256.Sum256(content)
				hashStr := string(h[:])
				if seenHashes[hashStr] {
					return nil
				}
				seenHashes[hashStr] = true
			}

			ext := strings.TrimPrefix(filepath.Ext(name), ".")
			lang := findLanguage(name, ext, content, extMap, filenameMap, opts)

			if lang == nil && opts.RemapUnknown == "" {
				return nil
			}

			job := CountFile(path, name, ext, content, lang, opts)
			if job == nil {
				return nil
			}

			if opts.NoMin && job.Minified {
				return nil
			}
			if opts.NoGen && job.Generated {
				return nil
			}
			if opts.NoMinGen && (job.Minified || job.Generated) {
				return nil
			}
			if opts.NoLarge {
				if job.Bytes > opts.LargeByteCount || job.Lines > opts.LargeLineCount {
					return nil
				}
			}

			if len(opts.IncludeExt) > 0 {
				inc := false
				for _, ie := range opts.IncludeExt {
					if strings.EqualFold(ext, ie) {
						inc = true
						break
					}
				}
				if !inc {
					return nil
				}
			}

			if len(opts.ExcludeExt) > 0 {
				for _, ee := range opts.ExcludeExt {
					if strings.EqualFold(ext, ee) {
						return nil
					}
				}
			}

			jobs = append(jobs, job)
			return nil
		})
	}

	return jobs, nil
}

func processSingleFile(path string, extMap map[string]*Language, filenameMap map[string]*Language, opts *Options) *FileJob {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	name := filepath.Base(path)
	ext := strings.TrimPrefix(filepath.Ext(name), ".")
	lang := findLanguage(name, ext, content, extMap, filenameMap, opts)
	return CountFile(path, name, ext, content, lang, opts)
}

func findLanguage(name string, ext string, content []byte, extMap map[string]*Language, filenameMap map[string]*Language, opts *Options) *Language {
	if l, ok := filenameMap[strings.ToLower(name)]; ok {
		return l
	}
	if l, ok := extMap[strings.ToLower(ext)]; ok {
		return l
	}

	if len(content) > 2 && content[0] == '#' && content[1] == '!' {
		firstLine := string(bytes.SplitN(content, []byte("\n"), 2)[0])
		if strings.Contains(firstLine, "python") {
			return extMap["py"]
		} else if strings.Contains(firstLine, "bash") || strings.Contains(firstLine, "sh") {
			return extMap["sh"]
		} else if strings.Contains(firstLine, "node") || strings.Contains(firstLine, "js") {
			return extMap["js"]
		} else if strings.Contains(firstLine, "perl") {
			return extMap["pl"]
		} else if strings.Contains(firstLine, "ruby") {
			return extMap["rb"]
		} else if strings.Contains(firstLine, "php") {
			return extMap["php"]
		}
	}

	return nil
}

func GroupAndSortSummaries(jobs []*FileJob, opts *Options) []*LanguageSummary {
	summaryMap := make(map[string]*LanguageSummary)

	for _, job := range jobs {
		langName := job.Language
		if (opts.Min || opts.NoMin || opts.MinGen || opts.NoMinGen) && job.Minified {
			langName += " (min)"
		} else if (opts.Gen || opts.NoGen || opts.MinGen || opts.NoMinGen) && job.Generated {
			langName += " (gen)"
		}

		s, ok := summaryMap[langName]
		if !ok {
			s = &LanguageSummary{
				Name: langName,
			}
			summaryMap[langName] = s
		}

		s.Count++
		s.Lines += job.Lines
		s.Code += job.Code
		s.Comment += job.Comment
		s.Blank += job.Blank
		s.Complexity += job.Complexity
		s.Bytes += job.Bytes
		s.ULOC += job.Uloc
		if job.MaxLineLength > s.MaxLineLength {
			s.MaxLineLength = job.MaxLineLength
		}
		s.Files = append(s.Files, job)
	}

	var summaries []*LanguageSummary
	for _, s := range summaryMap {
		summaries = append(summaries, s)
	}

	sortSummaries(summaries, opts.SortBy)

	for _, s := range summaries {
		sortFiles(s.Files, opts.SortBy)
	}

	return summaries
}

func sortSummaries(summaries []*LanguageSummary, sortBy string) {
	sort.Slice(summaries, func(i, j int) bool {
		switch strings.ToLower(sortBy) {
		case "name":
			return strings.ToLower(summaries[i].Name) < strings.ToLower(summaries[j].Name)
		case "lines":
			if summaries[i].Lines != summaries[j].Lines {
				return summaries[i].Lines > summaries[j].Lines
			}
		case "blanks", "blank":
			if summaries[i].Blank != summaries[j].Blank {
				return summaries[i].Blank > summaries[j].Blank
			}
		case "code":
			if summaries[i].Code != summaries[j].Code {
				return summaries[i].Code > summaries[j].Code
			}
		case "comments", "comment":
			if summaries[i].Comment != summaries[j].Comment {
				return summaries[i].Comment > summaries[j].Comment
			}
		case "complexity":
			if summaries[i].Complexity != summaries[j].Complexity {
				return summaries[i].Complexity > summaries[j].Complexity
			}
		default: // files
			if summaries[i].Count != summaries[j].Count {
				return summaries[i].Count > summaries[j].Count
			}
		}
		return strings.ToLower(summaries[i].Name) < strings.ToLower(summaries[j].Name)
	})
}

func sortFiles(files []*FileJob, sortBy string) {
	sort.Slice(files, func(i, j int) bool {
		switch strings.ToLower(sortBy) {
		case "name":
			return strings.ToLower(files[i].Location) < strings.ToLower(files[j].Location)
		case "lines":
			if files[i].Lines != files[j].Lines {
				return files[i].Lines > files[j].Lines
			}
		case "blanks", "blank":
			if files[i].Blank != files[j].Blank {
				return files[i].Blank > files[j].Blank
			}
		case "code":
			if files[i].Code != files[j].Code {
				return files[i].Code > files[j].Code
			}
		case "comments", "comment":
			if files[i].Comment != files[j].Comment {
				return files[i].Comment > files[j].Comment
			}
		case "complexity":
			if files[i].Complexity != files[j].Complexity {
				return files[i].Complexity > files[j].Complexity
			}
		default:
			if files[i].Lines != files[j].Lines {
				return files[i].Lines > files[j].Lines
			}
		}
		return strings.ToLower(files[i].Location) < strings.ToLower(files[j].Location)
	})
}
